1	import React from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
5	
6	// Exported (Figma-fidelity audit fix, 2026-09-19) so this is the one real source of these
7	// accessible names — zimmQuantityStepper/index.test.tsx and product-item/index.test.tsx both
8	// used to hardcode their own independent copy of the same two strings under local
9	// DECREMENT_NAME/INCREMENT_NAME constants, a real duplication a Tester pass found while
10	// reviewing this step's own new AC6 tests, which had deepened it further in both files.
11	export const messages = defineMessages({
12	  decrement: { id: 'zimm_quantity_stepper.decrement', defaultMessage: 'Decrease quantity' },
13	  increment: { id: 'zimm_quantity_stepper.increment', defaultMessage: 'Increase quantity' },
14	});
15	
16	/** Cart-line minimum meaningful quantity. 0 would mean "remove the line", a separate action this
17	 *  molecule does not own — see ZimmQuantityStepperProps.min. */
18	const MIN_DEFAULT = 1;
19	
20	export type ZimmQuantityStepperProps = {
21	  /** Current quantity rendered between the two buttons. */
22	  quantity: number;
23	  /** Lower bound (inclusive) — decrement disables at this value. Defaults to 1. */
24	  min?: number;
25	  /**
26	   * Upper bound (inclusive) — increment disables at this value. Always required: the caller
27	   * (inventory ATS, or a hardcoded per-SKU cap — see project memory on max order quantity) is the
28	   * one that knows the real ceiling. This molecule never computes or guesses one.
29	   */
30	  max: number;
31	  /**
32	   * Fully out-of-stock / unavailable for this line — forces BOTH buttons inert regardless of
33	   * where `quantity` sits between `min`/`max`, and dims the value display to match. This molecule
34	   * does not derive availability itself (no inventory lookups here) — the caller passes the
35	   * already-resolved flag.
36	   */
37	  isUnavailable?: boolean;
38	  /** Called with the computed next quantity (`quantity - 1`) when decrement is pressed while
39	   *  active. Never called while the decrement button is inert. */
40	  onDecrement: (nextQuantity: number) => void;
41	  /** Called with the computed next quantity (`quantity + 1`) when increment is pressed while
42	   *  active. Never called while the increment button is inert. */
43	  onIncrement: (nextQuantity: number) => void;
44	  /**
45	   * Id of an element (e.g. an active `ZimmInlineMessage`) describing this control's current
46	   * quantity/availability state — SFCC-795 plan step 3.6. Forwarded to BOTH buttons' own
47	   * `aria-describedby`, not just one: the message describes the stepper as a whole (e.g. "Maximum
48	   * purchase quantity reached for this size" is equally relevant whichever direction a shopper
49	   * reaches for), not one direction over the other. Undefined (every caller before this addition)
50	   * omits the attribute on both buttons entirely, unchanged from before this prop existed.
51	   */
52	  ariaDescribedBy?: string;
53	};
54	
55	/**
56	 * Molecule — cart-line quantity stepper (SFCC-271). Composes two `ZimmButton variant="icon"`
57	 * controls (hover/press/focus/disabled states are entirely zimmButton.css.ts's own, unchanged
58	 * here) around a numeric value display, styled by the co-located zimmQuantityStepper.css.ts.
59	 *
60	 * Controlled, not stateful: this component never mutates `quantity` itself, it only reports the
61	 * caller's next intended value via `onDecrement`/`onIncrement` — the actual basket update (an
